func calculateOffset(page: Int, pageSize: Int) -> Int {
    return (page - 1) * pageSize
}

let offset = calculateOffset(page: 3, pageSize: 20)
print("Offset: \(offset)")

struct Item: Identifiable {
    let id: Int
}

let list1 = [Item(id: 1), Item(id: 2)]
let list2 = [Item(id: 2), Item(id: 3)]
let existingIDs = Set(list1.map(\.id))
let fresh = list2.filter { !existingIDs.contains($0.id) }
print("Fresh count: \(fresh.count)")

struct Paginator {
    var isLoading = true
    var executed = false

    mutating func loadNext() {
        guard !isLoading else {
            return
        }
        executed = true
    }
}

var p = Paginator()
p.loadNext()
print("Executed: \(p.executed)")

struct PageResult {
    let nextCursor: String?
}

let result = PageResult(nextCursor: nil)
let hasMore = result.nextCursor != nil
print("Has more: \(hasMore)")

struct FeedState {
    var items = ["A", "B", "C"]
    var nextCursor: String? = "cursor_99"

    mutating func refresh() {
        items.removeAll()
        nextCursor = nil
    }
}

var state = FeedState()
state.refresh()
print("Items: \(state.items.count), Cursor: \(state.nextCursor ?? "none")")

struct CursorBatch {
    let records: [String]
    let cursor: Int?
}

var allRecords: [String] = []
var activeCursor: Int? = 10

let batch = CursorBatch(records: ["Item X", "Item Y"], cursor: 12)
allRecords.append(contentsOf: batch.records)
activeCursor = batch.cursor

print("Count: \(allRecords.count), Cursor: \(activeCursor ?? 0)")

