questions.modelAnswer:
func isThresholdReached(currentIndex: Int, totalCount: Int, threshold: Int) -> Bool {
    guard totalCount >= threshold else {
        return false
    }
    return currentIndex >= (totalCount - threshold)
}

let hit = isThresholdReached(currentIndex: 16, totalCount: 20, threshold: 5)
let miss = isThresholdReached(currentIndex: 10, totalCount: 20, threshold: 5)
print("Hit: \(hit), Miss: \(miss)")
